import re

import pytest


_TITLE_RE = re.compile(r"<title(?:\s[^>]*)?>(.*?)</title\s*>", re.IGNORECASE | re.DOTALL)


def title_of(html: str) -> str:
    """Return the text between <title> and </title> in html.

    Tag matching is case-insensitive and the opening tag may carry
    attributes. Returns an empty string if there is no complete
    title element. Only the first title element is considered.
    The text is returned as written, without stripping or unescaping.
    Pure string processing; performs no network access.
    """
    m = _TITLE_RE.search(html)
    return m.group(1) if m else ""


def test_basic() -> None:
    assert title_of("<html><head><title>Hello</title></head></html>") == "Hello"


def test_no_title() -> None:
    assert title_of("<html><body>Hi</body></html>") == ""


def test_empty_input() -> None:
    assert title_of("") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive() -> None:
    assert title_of("<HTML><TITLE>Upper</TITLE></HTML>") == "Upper"
    assert title_of("<Title>Mixed</tItLe>") == "Mixed"


def test_attributes_on_open_tag() -> None:
    assert title_of('<title id="t" class="x">With attrs</title>') == "With attrs"


def test_unclosed_title() -> None:
    assert title_of("<title>Never closed") == ""


def test_close_without_open() -> None:
    assert title_of("oops</title>") == ""


def test_first_title_wins() -> None:
    assert title_of("<title>One</title><title>Two</title>") == "One"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  spaced \n out  </title>") == "  spaced \n out  "


def test_multiline_title() -> None:
    assert title_of("<title>\nLine1\nLine2\n</title>") == "\nLine1\nLine2\n"


def test_entities_not_unescaped() -> None:
    assert title_of("<title>A &amp; B</title>") == "A &amp; B"


def test_does_not_match_titlefoo_tag() -> None:
    assert title_of("<titlefoo>x</titlefoo>") == ""


@pytest.mark.parametrize(
    ("html", "expected"),
    [
        ("<title>a</title>", "a"),
        ("<head><title>b</title></head>", "b"),
        ("no tags here", ""),
    ],
)
def test_parametrized(html: str, expected: str) -> None:
    assert title_of(html) == expected

